<?php

namespace App\Database\Seeds;

use CodeIgniter\Database\Seeder;

/**
 * Loads app/Database/Data/data.sql (generated by `php spark db:export`).
 *
 *   php spark db:seed InitialDataSeeder
 *
 * Safe to run repeatedly: it does nothing when the database already holds
 * users or customers. To overwrite an existing database, set the environment
 * variable RML_FORCE_SEED=1; every exported table is then emptied and reloaded.
 */
class InitialDataSeeder extends Seeder
{
	public function run()
	{
		$file = APPPATH . 'Database/Data/data.sql';
		if (! is_file($file)) {
			echo "No data file at {$file}; nothing to seed.\n";

			return;
		}

		$force = in_array(strtolower((string) getenv('RML_FORCE_SEED')), ['1', 'true', 'yes'], true);
		if (! $force && $this->hasData()) {
			echo "Database already has data; skipping InitialDataSeeder (set RML_FORCE_SEED=1 to overwrite).\n";

			return;
		}

		$this->db->query('SET FOREIGN_KEY_CHECKS = 0');
		$this->db->query("SET SESSION sql_mode = 'NO_ENGINE_SUBSTITUTION'");

		$fh        = fopen($file, 'rb');
		$truncated = [];
		$n         = 0;
		while (($line = fgets($fh)) !== false) {
			$line = rtrim($line, "\r\n");
			if ($line === '' || str_starts_with($line, '--')) {
				continue;
			}
			if (preg_match('/^INSERT INTO `([^`]+)`/', $line, $m) && ! isset($truncated[$m[1]])) {
				$this->db->query('TRUNCATE TABLE `' . $m[1] . '`');
				$truncated[$m[1]] = true;
			}
			$this->db->query(rtrim($line, ';'));
			$n++;
		}
		fclose($fh);

		$this->db->query('SET FOREIGN_KEY_CHECKS = 1');
		echo 'Loaded ' . count($truncated) . " tables ({$n} insert statements).\n";
	}

	private function hasData(): bool
	{
		foreach (['tbl_users', 'customerdetails'] as $table) {
			if ($this->db->tableExists($table) && $this->db->table($table)->countAllResults() > 0) {
				return true;
			}
		}

		return false;
	}
}
